    assert receipts.saved == {"ORD-3": "EUR 10.50 -> DECLINED"}


def test_a_declined_payment_is_reported_as_declined() -> None:
    handler = AuthorizePayment(AlwaysAnswers(AuthorizationOutcome.DECLINED), InMemoryReceiptStore())

    assert handler.handle("ORD-4", Money(Decimal("1"), "EUR")) is AuthorizationOutcome.DECLINED


def test_the_handler_is_declared_final() -> None:
    assert getattr(AuthorizePayment, "__final__", False) is True
